using Full.NET.Data.Abstractions;

namespace Full.NET.Modules.Ai.Persistence;

/// <summary>授权、任务和累计额度只写 AI 自有表；任务创建与授权次数消耗共用短事务。</summary>
internal static class AiKnowledgeIndexGrantSql
{
    private const string Columns = "grant_row.Id,grant_row.TenantId,grant_row.KnowledgeBaseId,grant_row.OwnerUserId,grant_row.ClientRequestId,grant_row.KnowledgeBaseVersion,grant_row.ModelConfigId,grant_row.ModelConfigVersion,grant_row.SessionJson,grant_row.ExpiresAtUtc,grant_row.DocumentLimit,grant_row.AdmittedDocuments,grant_row.InputTokenLimitPerDocument,grant_row.IsRevoked,grant_row.Version";
    // 无任务时直接返回整数零；MySQL 的 CAST 目标类型不支持 BIGINT，行读取器统一转换为 Int64。
    private const string EmptyTask = ",NULL AS TaskId,-1 AS LastBatchOrdinal,0 AS ReservedInputTokens";
    private const string Host = "grant_row.TenantId IS NULL";
    private const string Tenant = "grant_row.TenantId=@TenantId";
    private const string Owner = "grant_row.OwnerUserId=@OwnerUserId AND grant_row.KnowledgeBaseId=@KnowledgeBaseId AND ";
    private const string Read = "SELECT " + Columns + EmptyTask + " FROM fn_ai_index_grant AS grant_row WHERE " + Owner;
    internal static readonly SqlStatement FindHost = new("ai.index_grant.find_host", Read + Host + " AND grant_row.Id=@GrantId", SqlDataScope.HostOnly);
    internal static readonly SqlStatement FindTenant = new("ai.index_grant.find_tenant", Read + Tenant + " AND grant_row.Id=@GrantId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement LoadHost = new("ai.index_grant.load_host", "SELECT " + Columns + EmptyTask + " FROM fn_ai_index_grant AS grant_row WHERE grant_row.Id=@GrantId AND " + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement LoadTenant = new("ai.index_grant.load_tenant", "SELECT " + Columns + EmptyTask + " FROM fn_ai_index_grant AS grant_row WHERE grant_row.Id=@GrantId AND " + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement ClientHost = new("ai.index_grant.client_host", Read + Host + " AND grant_row.ClientRequestId=@ClientRequestId", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ClientTenant = new("ai.index_grant.client_tenant", Read + Tenant + " AND grant_row.ClientRequestId=@ClientRequestId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement ListSqlServerHost = new("ai.index_grant.list_sqlserver_host", "SELECT TOP (32) " + Columns + EmptyTask + " FROM fn_ai_index_grant AS grant_row WHERE " + Owner + Host + " AND (@HasCursor=0 OR grant_row.Id<@AfterId) ORDER BY grant_row.Id DESC", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ListSqlServerTenant = new("ai.index_grant.list_sqlserver_tenant", "SELECT TOP (32) " + Columns + EmptyTask + " FROM fn_ai_index_grant AS grant_row WHERE " + Owner + Tenant + " AND (@HasCursor=0 OR grant_row.Id<@AfterId) ORDER BY grant_row.Id DESC", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement ListMySqlHost = new("ai.index_grant.list_mysql_host", Read + Host + " AND (@HasCursor=0 OR grant_row.Id<@AfterId) ORDER BY grant_row.Id DESC LIMIT 32", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ListMySqlTenant = new("ai.index_grant.list_mysql_tenant", Read + Tenant + " AND (@HasCursor=0 OR grant_row.Id<@AfterId) ORDER BY grant_row.Id DESC LIMIT 32", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);

    private const string Insert = "INSERT INTO fn_ai_index_grant (Id,TenantId,KnowledgeBaseId,OwnerUserId,ClientRequestId,KnowledgeBaseVersion,ModelConfigId,ModelConfigVersion,SessionJson,ExpiresAtUtc,DocumentLimit,AdmittedDocuments,InputTokenLimitPerDocument,IsRevoked,Version,CreatedAtUtc) SELECT @GrantId,knowledge.TenantId,knowledge.Id,knowledge.OwnerUserId,@ClientRequestId,knowledge.Version,model.Id,model.Version,@SessionJson,@ExpiresAtUtc,@DocumentLimit,0,@InputTokenLimitPerDocument,0,1,@Now FROM fn_ai_knowledge_base AS knowledge INNER JOIN fn_ai_model_config AS model ON model.Id=knowledge.EmbeddingModelConfigId AND model.Version=knowledge.EmbeddingModelVersion WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.Version=@KnowledgeBaseVersion AND model.Id=@ModelConfigId AND model.Version=@ModelConfigVersion AND knowledge.IsEnabled=1 AND model.IsEnabled=1 AND (model.TenantId IS NULL OR model.TenantId=knowledge.TenantId) AND ";
    internal static readonly SqlStatement InsertHost = new("ai.index_grant.insert_host", Insert + "knowledge.TenantId IS NULL", SqlDataScope.HostOnly);
    internal static readonly SqlStatement InsertTenant = new("ai.index_grant.insert_tenant", Insert + "knowledge.TenantId=@TenantId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string Bound = "Id=@GrantId AND KnowledgeBaseId=@KnowledgeBaseId AND OwnerUserId=@OwnerUserId AND ";
    private const string Revoke = "UPDATE fn_ai_index_grant SET IsRevoked=1,Version=Version+1 WHERE " + Bound + "Version=@GrantVersion AND Version<2147483647 AND ";
    internal static readonly SqlStatement RevokeHost = new("ai.index_grant.revoke_host", Revoke + "TenantId IS NULL", SqlDataScope.HostOnly);
    internal static readonly SqlStatement RevokeTenant = new("ai.index_grant.revoke_tenant", Revoke + "TenantId=@TenantId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string Consume = "UPDATE fn_ai_index_grant SET AdmittedDocuments=AdmittedDocuments+1,Version=Version+1 WHERE " + Bound + "IsRevoked=0 AND ExpiresAtUtc>@Now AND AdmittedDocuments<DocumentLimit AND Version=@GrantVersion AND Version<2147483647 AND KnowledgeBaseVersion=@KnowledgeBaseVersion AND ";
    internal static readonly SqlStatement ConsumeHost = new("ai.index_grant.consume_host", Consume + "TenantId IS NULL", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ConsumeTenant = new("ai.index_grant.consume_tenant", Consume + "TenantId=@TenantId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string Attach = "INSERT INTO fn_ai_index_grant_item (Id,TenantId,GrantId,TaskId,LastBatchOrdinal,ReservedInputTokens) SELECT @GrantItemId,grant_row.TenantId,grant_row.Id,task.Id,-1,0 FROM fn_ai_index_grant AS grant_row INNER JOIN fn_ai_knowledge_index_task AS task ON task.Id=@TaskId AND task.KnowledgeBaseVersion=grant_row.KnowledgeBaseVersion AND task.ModelConfigId=grant_row.ModelConfigId AND task.ModelConfigVersion=grant_row.ModelConfigVersion WHERE " + Owner + "grant_row.Id=@GrantId AND grant_row.IsRevoked=0 AND grant_row.ExpiresAtUtc>@Now AND ";
    internal static readonly SqlStatement AttachHost = new("ai.index_grant.attach_host", Attach + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement AttachTenant = new("ai.index_grant.attach_tenant", Attach + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string Task = "SELECT " + Columns + ",item.TaskId,item.LastBatchOrdinal,item.ReservedInputTokens FROM fn_ai_index_grant_item AS item INNER JOIN fn_ai_index_grant AS grant_row ON grant_row.Id=item.GrantId WHERE item.TaskId=@TaskId AND " + Owner;
    internal static readonly SqlStatement TaskHost = new("ai.index_grant.task_host", Task + Host + " AND item.TenantId IS NULL", SqlDataScope.HostOnly);
    internal static readonly SqlStatement TaskTenant = new("ai.index_grant.task_tenant", Task + Tenant + " AND item.TenantId=@TenantId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string Charge = "UPDATE fn_ai_index_grant_item SET ReservedInputTokens=ReservedInputTokens+@InputTokens,LastBatchOrdinal=@BatchOrdinal WHERE TaskId=@TaskId AND GrantId=@GrantId AND LastBatchOrdinal=@PreviousOrdinal AND ReservedInputTokens<=@InputTokenLimitPerDocument-@InputTokens AND EXISTS (SELECT 1 FROM fn_ai_index_grant AS grant_row WHERE grant_row.Id=fn_ai_index_grant_item.GrantId AND " + Owner + "grant_row.IsRevoked=0 AND grant_row.ExpiresAtUtc>@Now AND ";
    internal static readonly SqlStatement ChargeHost = new("ai.index_grant.charge_host", Charge + Host + ") AND TenantId IS NULL", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ChargeTenant = new("ai.index_grant.charge_tenant", Charge + Tenant + ") AND TenantId=@TenantId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);

    private const string CandidateColumns = "knowledge.Id AS KnowledgeBaseId,document.Id AS DocumentId,version.Id AS VersionId,knowledge.OwnerUserId,document.Version AS DocumentVersion,knowledge.Version AS KnowledgeBaseVersion,model.Id AS ModelConfigId,model.Version AS ModelConfigVersion,version.ContentType";
    private const string Candidates = " FROM fn_ai_index_grant AS grant_row INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=grant_row.KnowledgeBaseId AND knowledge.OwnerUserId=grant_row.OwnerUserId AND knowledge.Version=grant_row.KnowledgeBaseVersion INNER JOIN fn_ai_model_config AS model ON model.Id=knowledge.EmbeddingModelConfigId AND model.Version=knowledge.EmbeddingModelVersion AND model.Id=grant_row.ModelConfigId AND model.Version=grant_row.ModelConfigVersion INNER JOIN fn_ai_knowledge_document AS document ON document.KnowledgeBaseId=knowledge.Id INNER JOIN fn_ai_knowledge_index_change AS intent ON intent.DocumentId=document.Id INNER JOIN fn_ai_knowledge_version AS version ON version.Id=intent.VersionId AND version.DocumentId=document.Id AND version.VersionNumber=intent.VersionNumber INNER JOIN fn_ai_knowledge_import AS operation ON operation.VersionId=version.Id AND operation.DocumentId=document.Id AND operation.FileId=version.FileId WHERE " + Owner + "grant_row.Id=@GrantId AND grant_row.IsRevoked=0 AND grant_row.ExpiresAtUtc>@Now AND grant_row.AdmittedDocuments<grant_row.DocumentLimit AND knowledge.IsEnabled=1 AND model.IsEnabled=1 AND (model.TenantId IS NULL OR model.TenantId=knowledge.TenantId) AND document.IsDeleted=0 AND operation.StateKey='completed' AND (version.ContentType IN ('text/plain','text/markdown') OR (@AllowPdf=1 AND version.ContentType='application/pdf') OR (@AllowDocx=1 AND version.ContentType='application/vnd.openxmlformats-officedocument.wordprocessingml.document')) AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_version AS newer WHERE newer.DocumentId=document.Id AND newer.VersionNumber>version.VersionNumber) AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_index_task AS task WHERE task.VersionId=version.Id AND task.DocumentVersion=document.Version AND task.KnowledgeBaseVersion=knowledge.Version) AND ";
    internal static readonly SqlStatement CandidatesSqlServerHost = new("ai.index_grant.candidates_sqlserver_host", "SELECT TOP (1) " + CandidateColumns + Candidates + Host + " AND knowledge.TenantId IS NULL ORDER BY document.Id", SqlDataScope.HostOnly);
    internal static readonly SqlStatement CandidatesSqlServerTenant = new("ai.index_grant.candidates_sqlserver_tenant", "SELECT TOP (1) " + CandidateColumns + Candidates + Tenant + " AND knowledge.TenantId=@TenantId ORDER BY document.Id", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement CandidatesMySqlHost = new("ai.index_grant.candidates_mysql_host", "SELECT " + CandidateColumns + Candidates + Host + " AND knowledge.TenantId IS NULL ORDER BY document.Id LIMIT 1", SqlDataScope.HostOnly);
    internal static readonly SqlStatement CandidatesMySqlTenant = new("ai.index_grant.candidates_mysql_tenant", "SELECT " + CandidateColumns + Candidates + Tenant + " AND knowledge.TenantId=@TenantId ORDER BY document.Id LIMIT 1", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);

    private const string Scan = " FROM fn_ai_index_grant WHERE IsRevoked=0 AND ExpiresAtUtc>@Now AND AdmittedDocuments<DocumentLimit AND (@HasCursor=0 OR Id>@AfterId) ORDER BY Id";
    internal static readonly SqlStatement ScanSqlServer = new("ai.index_grant.scan.sql_server", "SELECT TOP (@BatchSize) Id,TenantId" + Scan, SqlDataScope.Global);
    internal static readonly SqlStatement ScanMySql = new("ai.index_grant.scan.my_sql", "SELECT Id,TenantId" + Scan + " LIMIT @BatchSize", SqlDataScope.Global);
}
